def combination_sum(candidates, target):
    values = sorted(candidates)
    result = []
    combo = []
    def walk(start, remaining):
        if remaining == 0:
            result.append(list(combo))
            return
        for i in range(start, len(values)):
            value = values[i]
            if value > remaining:
                break
            combo.append(value)
            walk(i, remaining - value)
            combo.pop()
    walk(0, target)
    return sorted(result)

