def combination_sum(candidates, target):
    found = set()
    combo = []
    def walk(remaining):
        if remaining == 0:
            found.add(tuple(sorted(combo)))
            return
        for value in sorted(candidates):
            if value <= remaining:
                combo.append(value)
                walk(remaining - value)
                combo.pop()
    walk(target)
    return [list(item) for item in sorted(found)]
